// Le Guess Who? 2026 rooms and walking zones: static reference data for the
// lgw26 migration (generated by `npm run import:lgw -- --sql`) and the
// importer's room lookup. An unknown room is a hard failure, so a new venue
// on leguesswho.com never silently becomes an invented Stage row.
//
// Zones group rooms whose doors are a few minutes' walk apart, by the pins on
// each venue's own leguesswho.com page (snapshot `venues`). They're ordered
// by walking time from TivoliVredenburg (zones.ts), which is also the origin
// the zone headers measure from before a visitor taps a set.

export interface ZoneDef {
  /** Stable: it's in the Zone, Stage and ZoneWalk ids, so a rename never changes it. */
  slug: string;
  /** What the zone header shows. */
  name: string;
  /**
   * The name the lgw26 create migration inserted, when it has since been
   * renamed by a later migration. `--sql` reproduces the create migration
   * (migration-sql.ts), so it emits this; zones.test.ts checks that a rename
   * migration sets `name`.
   */
  createdAs?: string;
}

export const ZONES: ZoneDef[] = [
  { slug: "tivolivredenburg", name: "TivoliVredenburg" },
  // Renamed 2026-10-18 at Diogo's request (migration
  // 20261018200000_rename_lgw26_neude_zone).
  { slug: "neude", name: "Wijk C/Pijlsweerd", createdAs: "Neude" },
  { slug: "domplein", name: "Domplein" },
  { slug: "theater-utrecht", name: "Theater Utrecht" },
  { slug: "lucasbolwerk", name: "Lucasbolwerk" },
  { slug: "lombok", name: "Lombok" },
  { slug: "museumkwartier", name: "Museumkwartier" },
  { slug: "rotsoord", name: "Rotsoord" },
  { slug: "nijverheidskade", name: "Nijverheidskade" },
  { slug: "werkspoorkwartier", name: "Werkspoorkwartier" },
];

export const HUB_ZONE = "tivolivredenburg";

export interface RoomDef {
  /** Source venue name, as leguesswho.com spells it. */
  venue: string;
  /** Source room name, or null for a one-room venue. */
  room: string | null;
  /** Stage.slug (and the id suffix: `lgw26-<slug>`). */
  slug: string;
  /** What the grid's venue column and the mark sheet show. */
  name: string;
  zone: string;
}

