const roomKey = (venue: string, room: string | null) => `${venue}\u0000${room ?? ""}`;
const ROOM_BY_KEY = new Map(ROOMS.map((r) => [roomKey(r.venue, r.room), r]));

export function roomFor(venue: string, room: string | null): RoomDef {
  const found = ROOM_BY_KEY.get(roomKey(venue, room));
  if (!found) {
    throw new Error(
      `Unknown room "${venue}${room ? ` / ${room}` : ""}". Add it to ROOMS in scripts/lgw/venues.ts ` +
        `and a migration for its Stage row; refusing to invent one.`,
    );
  }
  return found;
}
